def oracle(m):
 k=m['kind']
 if k=='comma':
  trials=[];valid=[]
  for i in range(1,len(m['digits'])):
   text=m['digits'][:i]+','+m['digits'][i:];value=F(int(m['digits']),10**(len(m['digits'])-i));ok=F(m['low'])<value<F(m['high']);trials.append([text,str(value),ok])
   if ok:valid.append(text)
  assert valid==m['expected'];return dict(trials=trials,valid=valid)
 if k=='cards':
  strings=[];arrangements=[]
  for pp in permutations(m['cards']):
   ds=[m['cards'][i]for i in pp];s=ds[0]+','+''.join(ds[1:]);strings.append(s);arrangements.append([list(pp),s])
  strings=sorted(set(strings),key=lambda s:F(s.replace(',','.')));assert strings==m['expected_strings']and len(arrangements)==m['expected_arrangements'];return dict(arrangements=arrangements,distinct_strings=strings,numeric_values=[str(F(s.replace(',','.')))for s in strings],distinct_numeric_count=len(set(F(s.replace(',','.'))for s in strings)))
 if k=='scale':
  a,b=F(m['old']),F(m['new']);sa,sb=6*a*a,6*b*b;va,vb=a*a*a,b*b*b;sr,vr=sb/sa,vb/va;assert sr==F(m['expected_surface_ratio'])and vr==F(m['expected_volume_ratio']);return dict(old_surface=str(sa),new_surface=str(sb),old_volume=str(va),new_volume=str(vb),surface_ratio=str(sr),volume_ratio=str(vr),dimensional_factor_check=sr==(b/a)*(b/a)and vr==(b/a)*(b/a)*(b/a))
 if k=='paint':
  n=m['n'];cnt=Counter();faceincidences=0;assign=[]
  for x,y,z in product(range(n),repeat=3):
   sides=dict(xmin=x==0,xmax=x==n-1,ymin=y==0,ymax=y==n-1,zmin=z==0,zmax=z==n-1);faces=sum(sides[s]for s in m['painted_sides']);cnt[str(faces)]+=1;faceincidences+=faces;assign.append([[x,y,z],faces])
  assert dict(cnt)==m['expected']and sum(cnt.values())==n**3 and faceincidences==len(m['painted_sides'])*n*n;return dict(cube_assignments=assign,categories=dict(cnt),painted_face_incidences=faceincidences,outer_face_check=len(m['painted_sides'])*n*n)
 if k=='triangle_ratio':
  bs=list(map(F,m['bases']));h=2*F(m['total'])/sum(bs);areas=[b*h/2 for b in bs];assert areas==list(map(F,m['expected_areas']));return dict(independent_inferred_height=str(h),areas=list(map(str,areas)),area_sum=str(sum(areas)))
 if k=='triangle_unequal_heights':
  areas=[F(b)*F(h)/2 for b,h in zip(m['bases'],m['heights'])];assert areas==list(map(F,m['expected_areas']));return dict(areas=list(map(str,areas)),area_ratio=str(areas[0]/areas[1]),base_ratio=str(F(m['bases'][0])/F(m['bases'][1])),sameheight=False)
 if k=='parallel_apex':
  # Shoelace determinant on explicit oracle coordinates, independent of pupil
  # constantheight explanation; apex can be outside base span.
  b,h=F(m['base']),F(m['height']);aa=[]
  for x in map(F,m['apex_x_values']):
   polygon=[(F(0),F(0)),(b,F(0)),(x,h)];cross=sum(polygon[i][0]*polygon[(i+1)%3][1]-polygon[(i+1)%3][0]*polygon[i][1]for i in range(3));aa.append(abs(cross)/2)
  assert all(a==F(m['expected_area'])for a in aa);return dict(apex_x=m['apex_x_values'],shoelace_areas=list(map(str,aa)),all_equal=True)
 if k=='nonparallel_apex':
  b=F(m['base']);areas=[b*F(h)/2 for h in m['heights']];assert areas==list(map(F,m['expected_areas']));return dict(areas=list(map(str,areas)),change=str(areas[1]-areas[0]),equal=False)
 raise ValueError(k)

